package com.example.familymenu.family.service;
import com.example.familymenu.common.exception.BusinessException; import com.example.familymenu.family.domain.*; import com.example.familymenu.family.repository.FamilyRepository; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import java.util.*;
@Service @RequiredArgsConstructor public class FamilyServiceImpl implements FamilyService { private final FamilyRepository repo; public Family create(String n,String o){return repo.create(n,o);} public Family get(Long id){return repo.findById(id).orElseThrow(()->new BusinessException("家庭不存在: "+id));} public List<FamilyMember> members(Long id){get(id);return repo.findMembers(id);} public FamilyMember addMember(Long id,String n,String r){get(id); String role=r==null||r.trim().isEmpty()?"MEMBER":r.toUpperCase(); if(!Arrays.asList("OWNER","ADMIN","MEMBER").contains(role)) throw new BusinessException("成员角色不合法"); for(FamilyMember m: repo.findMembers(id)){if(m.getNickname().equals(n)) throw new BusinessException("该成员已在家庭中");} return repo.addMember(id,n,role);} public void removeMember(Long id,Long mid){get(id);if(!repo.removeMember(id,mid)) throw new BusinessException("成员不存在或不能移除拥有者");} }
